{
  "assessment": "This change introduces `subs/prorate.py` but leaves `days_in(year, month)` hardcoded to always return 30, completely ignoring the calendar month and year passed as arguments. Consequently, refunds for any billing month that does not have exactly thirty days (like February's twenty-eight) will still be calculated incorrectly against a static denominator instead of the actual month length.",
  "findings": [
    {
      "actual": "30",
      "at": "subs/prorate.py:12",
      "call": "python -c \"from subs.prorate import days_in; print(days_in(2026, 2))\"",
      "defect": "`days_in` ignores its parameters and always returns 30",
      "expected": "28"
    }
  ]
}
